import{_ as a,o as r,c as t,a5 as s}from"./chunks/framework.pJebtgMf.js";const m=JSON.parse('{"title":"AI 动态 · 2026-08-26","description":"","frontmatter":{"title":"AI 动态 · 2026-08-26","date":"2026-08-26T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-26.md","filePath":"news/2026-08/ai-news-2026-08-26.md","lastUpdated":null}'),n={name:"news/2026-08/ai-news-2026-08-26.md"};function i(o,e,l,c,p,h){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-08-26" tabindex="-1">AI 动态 · 2026-08-26 <a class="header-anchor" href="#ai-动态-·-2026-08-26" aria-label="Permalink to &quot;AI 动态 · 2026-08-26&quot;">​</a></h1><blockquote><p>截至 2026-08-26。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="z-ai-确认是神秘开源模型-ox-alpha-背后的实验室" tabindex="-1">Z.ai 确认是神秘开源模型 Ox Alpha 背后的实验室 <a class="header-anchor" href="#z-ai-确认是神秘开源模型-ox-alpha-背后的实验室" aria-label="Permalink to &quot;Z.ai 确认是神秘开源模型 Ox Alpha 背后的实验室&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-26">2026-08-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/2c3d0e1f99f4.jpg" alt="配图"></p><p>Z.ai 证实其正是神秘开源模型 Ox Alpha 的开发者，该模型此前在多个基准测试和排行榜上名列前茅。公司表示，Ox Alpha 的权重即将公开发布，这将为开源社区带来一款性能顶尖的模型。此举有望改变当前开源模型竞争格局，并引发社区对模型技术细节的广泛关注。对读者：关注 Ox Alpha 权重发布，评估其性能与许可证，考虑在自有项目中集成或进行二次开发。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/26/surprise-z-ai-is-the-ai-lab-behind-the-mysterious-ox-alpha-model/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="ibm-发布-granite-4-2-模型-聚焦本地-llm-与企业级-agent-能力" tabindex="-1">IBM 发布 Granite 4.2 模型，聚焦本地 LLM 与企业级 Agent 能力 <a class="header-anchor" href="#ibm-发布-granite-4-2-模型-聚焦本地-llm-与企业级-agent-能力" aria-label="Permalink to &quot;IBM 发布 Granite 4.2 模型，聚焦本地 LLM 与企业级 Agent 能力&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ars Technica AI</span><time datetime="2026-08-26">2026-08-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/44806627ce20.jpg" alt="配图"></p><p>IBM 推出新一代 Granite 4.2 模型系列，重点强化了 Agent 能力和企业级部署的可预测性。该系列模型顺应了当前对本地 LLM 的兴趣浪潮，旨在为企业提供更可控、更安全的 AI 解决方案。Granite 4.2 支持通过 Ollama 等工具在本地运行，降低了企业采用大模型的门槛。对读者：关注 Granite 4.2 的本地部署方案，评估其 Agent 能力是否满足企业业务需求，可作为私有化部署的候选模型。</p><p class="news-entry-source"><a href="https://arstechnica.com/ai/2026/08/ibms-new-granite-4-2-models-ride-the-wave-of-interest-in-local-llms/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="_535b-大模型-marin-开启-直播-训练-代码、数据与-loss-全公开" tabindex="-1">535B 大模型 Marin 开启“直播”训练，代码、数据与 Loss 全公开 <a class="header-anchor" href="#_535b-大模型-marin-开启-直播-训练-代码、数据与-loss-全公开" aria-label="Permalink to &quot;535B 大模型 Marin 开启“直播”训练，代码、数据与 Loss 全公开&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-26">2026-08-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/0aae9a7a8a4c.png" alt="配图"></p><p>斯坦福 CRFM 主导的开放基础模型项目 Marin 启动 535B 参数模型训练，并史无前例地实时公开训练曲线、数据配方和系统配置。该项目计划处理 18.75 万亿 Token，运行在 11 套 GB200 NVL72 集群上，总计算量约 2.7×10²⁴ FLOPs。此举旨在推动可复现的协作式 AI 开发，吴恩达也公开表示支持。对读者：关注 Marin 项目公开的训练细节，可从中学习大规模模型训练的实践经验，并跟踪其最终成果。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/y7KTOS9YbBz0OcoyiweQ?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="韩国-ai-初创-wrtn-以-8-7-亿美元估值融资-加速全球扩张" tabindex="-1">韩国 AI 初创 Wrtn 以 8.7 亿美元估值融资，加速全球扩张 <a class="header-anchor" href="#韩国-ai-初创-wrtn-以-8-7-亿美元估值融资-加速全球扩张" aria-label="Permalink to &quot;韩国 AI 初创 Wrtn 以 8.7 亿美元估值融资，加速全球扩张&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Bloomberg</span><time datetime="2026-08-26">2026-08-26</time></p><p>韩国 AI 初创公司 Wrtn 完成新一轮融资，估值达到 8.7 亿美元。这笔资金将用于支持其全球扩张计划。Wrtn 是韩国领先的 AI 平台之一，此举表明亚洲 AI 市场持续获得资本青睐，竞争也日趋激烈。对读者：关注 Wrtn 的全球化产品策略，其发展路径可作为 AI 应用出海亚洲市场的参考案例。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMiyAFBVV95cUxQSTRlMlN3UlhkZnQ1NnJDVXlHSlRKRF9Ca25wX3VUZlN4Z1hsczlBQXBKZnhxWEc1d2wxRkN6S2tZT0pCb3FlSTR6SU00dW5rdVFVTDdyYmdxYTUxb19HX0c0TlJoYjFwZmpWck05Ry1JR2phREtnUEx5djdFQ2FiNEk4eEpRUk9welhZRTF0dUIwaXhMLWJ3c1J0MmNLZkNwY0ZfbzIwek5LeHozc0YySGxoalM1SXhjcGVIWENHLTJ4Q3hYYmwzbg?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="chatgpt-for-teachers-扩展至美国-55-个学区" tabindex="-1">ChatGPT for Teachers 扩展至美国 55 个学区 <a class="header-anchor" href="#chatgpt-for-teachers-扩展至美国-55-个学区" aria-label="Permalink to &quot;ChatGPT for Teachers 扩展至美国 55 个学区&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-08-26">2026-08-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/653ddf589a41.png" alt="配图"></p><p>OpenAI 宣布将其教育产品 ChatGPT for Teachers 扩展至美国 55 个学区，为超过 10 万名教育工作者和教职员工提供安全的 AI 工具、培训和支持。此举旨在通过共享实施模式，将 AI 代理工具交到教师手中，推动 AI 在教育领域的信任建设和规模化应用。对读者：教育科技从业者可关注该项目的实施模式与反馈，了解 AI 工具在 K-12 教育场景中的落地路径和挑战。</p><p class="news-entry-source"><a href="https://openai.com/index/bringing-chatgpt-for-teachers-to-more-us-school-districts" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="particle-推出-radar-平台-让播客可被搜索并供-ai-代理使用" tabindex="-1">Particle 推出 Radar 平台，让播客可被搜索并供 AI 代理使用 <a class="header-anchor" href="#particle-推出-radar-平台-让播客可被搜索并供-ai-代理使用" aria-label="Permalink to &quot;Particle 推出 Radar 平台，让播客可被搜索并供 AI 代理使用&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-26">2026-08-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/7027518ba07b.jpg" alt="配图"></p><p>Particle 发布播客智能平台 Radar，可转录和分析超过 13 万个播客节目，使其内容在网络上可搜索，并通过 API 和 MCP 协议向 AI 代理开放。该平台将播客这一非结构化音频内容转化为可被 AI 系统利用的结构化数据，拓展了 AI 代理的信息获取边界。对读者：开发者可通过 Radar 的 API 和 MCP 集成播客内容，为 AI 应用增加音频知识源，探索新的交互和内容发现方式。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/26/radar-makes-podcasts-searchable-and-usable-by-ai-agents/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="z-ai-确认是神秘-ox-alpha-模型背后的-ai-实验室" tabindex="-1">Z.ai 确认是神秘 Ox Alpha 模型背后的 AI 实验室 <a class="header-anchor" href="#z-ai-确认是神秘-ox-alpha-模型背后的-ai-实验室" aria-label="Permalink to &quot;Z.ai 确认是神秘 Ox Alpha 模型背后的 AI 实验室&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch</span><time datetime="2026-08-26">2026-08-26</time></p><p>Z.ai 正式确认其是神秘开源模型 Ox Alpha 的创造者，该模型此前在多个基准测试中表现优异，引发业界猜测。Z.ai 表示 Ox Alpha 的权重即将发布，这将为开源社区带来一款顶尖性能模型，并可能重塑开源模型竞争格局。对读者：关注 Ox Alpha 权重发布，评估其性能与许可证，考虑在自有项目中集成或进行二次开发。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMioAFBVV95cUxNWFR3QnVmLU5NNWtuQ0lITGFxTDREVWdJbE1wTFFNR0RVWExhV2lNR2sxMnF2Nmlud1FOSjVPaW82clVOcGtETW5oeDN0SDNPcmhKUDZHT043a1hzdnltSGVDSTZXamFYZE5uRWs0V3pNelVnRlBUVTZ1YlhaaF9KS0k2RVBJRkVGUklOYkZLZ29hMHd5aHRnMlA3cFRRNXhz?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="hugging-face-发布多向量嵌入模型训练与微调指南" tabindex="-1">Hugging Face 发布多向量嵌入模型训练与微调指南 <a class="header-anchor" href="#hugging-face-发布多向量嵌入模型训练与微调指南" aria-label="Permalink to &quot;Hugging Face 发布多向量嵌入模型训练与微调指南&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Hugging Face Blog</span><time datetime="2026-08-26">2026-08-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/e08c69fedc28.png" alt="配图"></p><p>Hugging Face 发布一篇详细指南，介绍如何使用 Sentence Transformers 库训练和微调多向量嵌入模型。文章涵盖了多向量模型的概念、微调原因、训练组件、数据集准备、损失函数选择等关键内容，并提供了从现有模型微调或从基础 Transformer 构建的完整路径。对读者：开发者可参考该指南，利用 Sentence Transformers 构建或微调多向量嵌入模型，以提升检索、RAG 等场景的语义理解能力。</p><p class="news-entry-source"><a href="https://huggingface.co/blog/train-multi-vector-encoder" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="browser-use-开源项目-让网站对-ai-代理可访问" tabindex="-1">browser-use 开源项目：让网站对 AI 代理可访问 <a class="header-anchor" href="#browser-use-开源项目-让网站对-ai-代理可访问" aria-label="Permalink to &quot;browser-use 开源项目：让网站对 AI 代理可访问&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">browser-use/browser-use</span><time datetime="2026-08-26">2026-08-26</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/c33a3d10cd34.png" alt="配图"></p><p>browser-use 是一个开源项目，旨在让网站对 AI 代理可访问，使 AI 能够轻松地自动化在线任务。该项目提供工具和接口，帮助开发者构建能够与网页交互的 AI 代理，实现表单填写、数据提取等自动化操作。对读者：开发者可探索 browser-use，将其集成到 AI 代理工作流中，实现更复杂的网页自动化任务，提升 Agent 的实用性。</p><p class="news-entry-source"><a href="https://github.com/browser-use/browser-use" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="css-新属性-animation-trigger-实现滚动触发动画" tabindex="-1">CSS 新属性 animation-trigger 实现滚动触发动画 <a class="header-anchor" href="#css-新属性-animation-trigger-实现滚动触发动画" aria-label="Permalink to &quot;CSS 新属性 animation-trigger 实现滚动触发动画&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">CSS-Tricks</span><time datetime="2026-08-26">2026-08-26</time></p><p>CSS-Tricks 介绍了新的 CSS 属性 animation-trigger，该属性允许开发者延迟 CSS 动画的开始，直到特定触发器发生。它通过监听命名触发器来控制动画的播放或暂停，为滚动触发动画提供了原生 CSS 解决方案，替代了传统的 JavaScript + Intersection Observer 方案。对读者：前端开发者可关注该属性的浏览器支持情况，在支持的场景中用它简化滚动动画实现，减少 JS 依赖。</p><p class="news-entry-source"><a href="https://css-tricks.com/almanac/properties/a/animation-trigger/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div>',8)])])}const g=a(n,[["render",i]]);export{m as __pageData,g as default};
